import pytest
from app import app, state

@pytest.fixture
def client():
    app.config['TESTING'] = True
    return app.test_client()

@pytest.fixture(autouse=True)
def reset_state():
    state['settings'].store_name = ''
    state['settings'].contact_details = ''
    state['settings'].currency = ''
    state['settings'].tax_settings = ''
    state['settings'].shipping_methods = []
    state['settings'].payment_options = []
    state['settings'].business_details = ''
    state['settings'].live = False
    state['products'].clear()
    state['customers'].clear()
    state['orders'].clear()
    yield


def test_setup_and_product_flow(client):
    r = client.post('/admin/setup', json={
        'store_name': 'Shop', 'contact_details': 'contact', 'currency': 'USD',
        'tax_settings': 'basic', 'shipping_methods': ['standard'],
        'payment_options': ['card'], 'business_details': 'legal'
    })
    assert r.status_code == 200
    assert r.get_json()['live'] is True

    p = client.post('/admin/products', json={'name': 'Widget', 'price': 10, 'stock': 2})
    pid = p.get_json()['id']
    assert client.get('/products').get_json()[0]['name'] == 'Widget'
    assert client.get('/low-stock').get_json()['warnings'][0]['id'] == pid


def test_customer_validation_and_checkout(client):
    product = client.post('/admin/products', json={'name': 'Widget', 'price': 10, 'stock': 2}).get_json()
    c = client.post('/customers', json={'name': 'A', 'address': {'name': 'A', 'street': 's', 'city': 'c', 'postal_code': 'p', 'country': 'US', 'email': 'a@example.com'}})
    cid = c.get_json()['id']
    order = client.post('/cart/checkout', json={'customer_id': cid, 'items': [{'product_id': product['id'], 'qty': 1}], 'shipping_method': 'standard'})
    assert order.status_code == 201
    assert order.get_json()['status'] == 'new'


def test_insufficient_stock_blocked(client):
    product = client.post('/admin/products', json={'name': 'Widget', 'price': 10, 'stock': 1}).get_json()
    c = client.post('/customers', json={'name': 'A', 'address': {'name': 'A', 'street': 's', 'city': 'c', 'postal_code': 'p', 'country': 'US', 'email': 'a@example.com'}}).get_json()
    r = client.post('/cart/checkout', json={'customer_id': c['id'], 'items': [{'product_id': product['id'], 'qty': 2}]})
    assert r.status_code == 400


def test_shipped_order_cannot_be_cancelled(client):
    product = client.post('/admin/products', json={'name': 'Widget', 'price': 10, 'stock': 2}).get_json()
    c = client.post('/customers', json={'name': 'A', 'address': {'name': 'A', 'street': 's', 'city': 'c', 'postal_code': 'p', 'country': 'US', 'email': 'a@example.com'}}).get_json()
    order = client.post('/cart/checkout', json={'customer_id': c['id'], 'items': [{'product_id': product['id'], 'qty': 1}]}).get_json()
    client.patch(f"/orders/{order['id']}", json={'status': 'shipped'})
    r = client.patch(f"/orders/{order['id']}", json={'status': 'cancelled'})
    assert r.status_code == 403
EOF

