    name: str
    email: str
    address: dict
    status: str = "active"
    role: str = "customer"

@dataclass
class Order:
    id: str
    customer_id: str
    items: List[dict]
    status: str = "new"
    shipping_method: str = ""
    payment_method: str = "card"
    total: float = 0.0
