        "sales": {"username": "sales", "password": "sales", "role": "sales"},
    },
}


def require_json(fields):
    data = request.get_json(silent=True) or {}
    missing = [f for f in fields if f not in data or data[f] in (None, "")]
    if missing:
        return None, (jsonify({"error": f"missing fields: {', '.join(missing)}"}), 400)
    return data, None


def customer_valid(address):
    required = ["name", "street", "city", "postal_code", "country"]
    if not all(address.get(k) for k in required):
        return False
    if not (address.get("phone") or address.get("email")):
        return False
    return True


def get_product(pid):
    return state["products"].get(pid)


@app.get("/")
def index():
    return jsonify({"service": "GAMMA-J Web Store", "ready": state["settings"].live})


@app.post("/admin/setup")
def setup():
    data = request.get_json(silent=True) or {}
    settings = state["settings"]
    settings.store_name = data.get("store_name", settings.store_name)
    settings.contact_details = data.get("contact_details", settings.contact_details)
    settings.currency = data.get("currency", settings.currency)
    settings.tax_settings = data.get("tax_settings", settings.tax_settings)
    settings.shipping_methods = data.get("shipping_methods", settings.shipping_methods)
    settings.payment_options = data.get("payment_options", settings.payment_options)
    settings.business_details = data.get("business_details", settings.business_details)
    settings.live = all([settings.store_name, settings.contact_details, settings.currency, settings.tax_settings, settings.shipping_methods, settings.payment_options, settings.business_details])
    return jsonify(asdict(settings))


