def list_products():
    return jsonify([asdict(p) for p in state["products"].values() if p.active])


@app.post("/admin/products")
def create_product():
    data = request.get_json(silent=True) or {}
    pid = str(uuid4())
    product = Product(
        id=pid,
        name=data.get("name", ""),
        price=float(data.get("price", 0)),
        stock=int(data.get("stock", 0)),
        active=bool(data.get("active", True)),
        low_stock_threshold=int(data.get("low_stock_threshold", 5)),
    )
    state["products"][pid] = product
    return jsonify(asdict(product)), 201


@app.patch("/admin/products/<pid>")
def update_product(pid):
    product = get_product(pid)
    if not product:
        return jsonify({"error": "not found"}), 404
    data = request.get_json(silent=True) or {}
    if "active" in data:
        product.active = bool(data["active"])
    if not product.active and any(k in data for k in ["name", "price", "stock", "low_stock_threshold"]):
        return jsonify({"error": "staff shall only be able to create or edit active catalog products"}), 403
    if "name" in data:
        product.name = data["name"]
    if "price" in data:
        product.price = float(data["price"])
    if "stock" in data:
        product.stock = int(data["stock"])
    if "low_stock_threshold" in data:
        product.low_stock_threshold = int(data["low_stock_threshold"])
    return jsonify(asdict(product))


@app.post("/customers")
def create_customer():
    data = request.get_json(silent=True) or {}
    if not customer_valid(data.get("address", {})):
        return jsonify({"error": "invalid customer record"}), 400
    email = data["address"]["email"]
    if any(c.email == email for c in state["customers"].values()):
        return jsonify({"error": "duplicate customer"}), 400
    cid = str(uuid4())
    customer = Customer(id=cid, name=data["name"], email=email, address=data["address"], status=data.get("status", "active"))
    state["customers"][cid] = customer
    return jsonify(asdict(customer)), 201


@app.get("/customers/<cid>")
