def update_customer(cid):
    customer = state["customers"].get(cid)
    if not customer:
        return jsonify({"error": "not found"}), 404
    data = request.get_json(silent=True) or {}
    if "status" in data:
        customer.status = data["status"]
    if "name" in data:
        customer.name = data["name"]
    if "address" in data and customer_valid(data["address"]):
        customer.address = data["address"]
    return jsonify(asdict(customer))


@app.post("/cart/checkout")
def checkout():
    data = request.get_json(silent=True) or {}
    customer_id = data.get("customer_id")
    customer = state["customers"].get(customer_id)
    if not customer:
        return jsonify({"error": "customer required"}), 400
    if customer.status in ["pending", "blocked", "held"]:
        return jsonify({"error": "customer account not eligible for checkout"}), 403
    if not customer_valid(customer.address):
        return jsonify({"error": "missing shipping details"}), 400
    items = data.get("items", [])
    if not items:
        return jsonify({"error": "empty cart"}), 400
    shipping_method = data.get("shipping_method", "standard")
    payment_method = data.get("payment_method", "card")
    total = 0.0
    for item in items:
        product = get_product(item.get("product_id"))
        qty = int(item.get("qty", 0))
        if not product or not product.active:
            return jsonify({"error": "product unavailable"}), 400
        if qty > product.stock:
            return jsonify({"error": "insufficient stock"}), 400
        total += product.price * qty
    order_id = str(uuid4())
    order = Order(id=order_id, customer_id=customer_id, items=items, shipping_method=shipping_method, payment_method=payment_method, total=round(total, 2))
    state["orders"][order_id] = order
    for item in items:
        state["products"][item["product_id"]].stock -= int(item.get("qty", 0))
    return jsonify(asdict(order)), 201


@app.get("/orders/<oid>")
def get_order(oid):
    order = state["orders"].get(oid)
    if not order:
        return jsonify({"error": "not found"}), 404
    return jsonify(asdict(order))


@app.patch("/orders/<oid>")
def update_order(oid):
    order = state["orders"].get(oid)
    if not order:
        return jsonify({"error": "not found"}), 404
    data = request.get_json(silent=True) or {}
    new_status = data.get("status")
    allowed = ["new", "paid", "packed", "shipped", "completed", "cancelled"]
    if new_status not in allowed:
        return jsonify({"error": "invalid status"}), 400
    if order.status == "shipped" and new_status == "cancelled":
        return jsonify({"error": "cannot cancel shipped order"}), 403
    order.status = new_status
    return jsonify(asdict(order))


@app.get("/low-stock")
def low_stock():
    warnings = [asdict(p) for p in state["products"].values() if p.stock <= p.low_stock_threshold]
    return jsonify({"warnings": warnings, "recipients": ["owner", "inventory"]})


@app.get("/shipping-options")
def shipping_options():
    return jsonify([
        {"method": "standard", "available": True, "cost_rule": "region based"},
        {"method": "express", "available": True, "cost_rule": "region and speed based"},
    ])


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000, debug=True)
